// n8n Code node (JavaScript)
// Pevně očekává vstupní text v: $json.content

const raw = $input.first().json.content;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Input field "content" is empty or not a string.');
}

// Mapování sekcí -> výstupní pole
const sectionToField = {
  'Email Subject':'email_subject_parsed',

  'Blog title': 'blog_title_parsed',
  'Blog Content': 'blog_text_parsed',
  'Blog CTA': 'blog_cta_label_parsed',

  'Project Title': 'project_title_parsed',
  'Project Content': 'project_text_parsed',
  'Project CTA': 'project_cta_label_parsed',

  'Collection Title': 'collection_title_parsed',
  'Collection Content': 'collection_text_parsed',
  'Collection CTA': 'collection_cta_parsed',

  'Pattern Title': 'pattern_title_parsed',
  'Pattern Content': 'pattern_text_parsed',
  'Pattern From': 'patternCollection_name_parsed',

  'CTA Content': 'cta_text_parsed',
  'CTA Button': 'cta_button_parsed',
};

// Najdi delimiter sekce
const sectionRegex = /^---\s*(.+?)\s*---\s*$/gm;

const matches = [];
let m;
while ((m = sectionRegex.exec(raw)) !== null) {
  matches.push({
    name: m[1],
    index: m.index,
    endOfHeader: sectionRegex.lastIndex
  });
}

// připrav výstup
const parsed = {};
for (const key of Object.values(sectionToField)) parsed[key] = '';

// vyřízni obsah sekcí
for (let i = 0; i < matches.length; i++) {
  const { name, endOfHeader } = matches[i];
  const nextStart = (i + 1 < matches.length) ? matches[i + 1].index : raw.length;

  let content = raw.slice(endOfHeader, nextStart);
  content = content.trim();

  const outField = sectionToField[name];
  if (outField) parsed[outField] = content;
}

// výstup
return [{ json: parsed }];
